"""Injected source-format contract; no SDK or vendor-specific classification."""
from __future__ import annotations
import importlib
import re
from typing import Any, Mapping, Protocol, Sequence

class SourceFormat(Protocol):
    version: str
    contract: dict[str, Any]
    def identity(self) -> dict[str, Any]: ...
    def context(self, events: Sequence[Mapping[str, Any]]) -> Any: ...
    def is_device(self, event: Mapping[str, Any], context: Any) -> bool: ...
    def category(self, event: Mapping[str, Any], context: Any) -> str: ...
    def normalizable(self, event: Mapping[str, Any], context: Any) -> bool: ...
    def task_type(self, event: Mapping[str, Any]) -> Any: ...
    def host_pid(self, event: Mapping[str, Any], context: Any) -> Any: ...
    def is_launch(self, event: Mapping[str, Any]) -> bool: ...
    def audit_dependencies(self, events: Sequence[Mapping[str,Any]], context: Any) -> list[dict]: ...
    def scope_facts(self, events: Sequence[Mapping[str,Any]], context: Any) -> dict: ...

def load_adapter(vendor: str) -> Any:
    if not isinstance(vendor, str) or not re.fullmatch(r'[a-z][a-z0-9_]*', vendor):
        raise ValueError('invalid rule family')
    try:
        return importlib.import_module('flagprof.vendors.' + vendor + '.importer')
    except ModuleNotFoundError as error:
        if error.name in ('flagprof.vendors.' + vendor, 'flagprof.vendors.' + vendor + '.importer'):
            raise ValueError('unsupported rule family: ' + vendor) from error
        raise
